<template>
  <main class="mobile-app" @mousedown.capture="focusedKey = ''">
    <header class="mobile-header"><b>XJTU</b><h1>XJTU课程规划助手</h1><button @click="redo">重做</button></header>
    <section class="week-control"><strong>{{ week === 0 ? '我的课表' : `第 ${week} 周` }}</strong><input v-model.number="week" min="0" max="18" type="range" /></section>

    <section class="card main-card">
      <nav class="tabs"><button :class="{ active: tab === 'schedule' }" @click="tab = 'schedule'">周课表</button><button :class="{ active: tab === 'search' }" @click="tab = 'search'">课程检索 {{ courses.length }}</button><button :class="{ active: tab === 'plan' }" @click="tab = 'plan'">培养方案 {{ planKeys.length }}</button></nav>

      <template v-if="tab === 'schedule'">
        <p class="hint">{{ week === 0 ? '第 0 周：汇总全部已上课表课程' : '点击课程可定位到培养方案' }}</p>
        <div class="schedule-scroll"><table class="schedule-table"><thead><tr><th>节次</th><th v-for="day in days" :key="day">{{ day }}</th></tr></thead><tbody><tr v-for="period in 11" :key="period" :class="{ split: period === 5 || period === 9 }"><th>{{ period }}</th><td v-for="day in 7" :key="day"><button v-for="item in displayedClasses(day, period)" :key="item.key" class="class-card" :style="{ backgroundColor: item.course.color }" @click.stop="focusPlan(item.course.key)"><b>{{ item.course.name }}</b><span>{{ item.course.className }} {{ item.course.teacher }}</span><small>{{ week === 0 ? `第${item.meeting.weekText}周@${item.meeting.room}` : item.meeting.room }}</small></button></td></tr></tbody></table></div>
      </template>

      <template v-else-if="tab === 'search'">
        <div class="filters"><input v-for="field in filterFields" :key="field.key" v-model="filters[field.key]" :placeholder="field.label" @input="searchPage = 1" /><button @click="clearFilters">清空</button></div>
        <div class="course-list"><article v-for="course in pagedCourses" :key="course.key" class="course-row"><div><code>{{ course.id }} · {{ course.credit }} 学分 · {{ course.college || '未填写学院' }}</code><h3>{{ course.name }}</h3><p>{{ course.className }} {{ course.teacher }}</p><small>◷ {{ courseTime(course) }}<br />⌖ {{ course.rooms }}</small></div><button :class="{ outlined: planKeys.includes(course.key) }" @click="addToPlan(course)">{{ planKeys.includes(course.key) ? '查看方案' : '加入方案' }}</button></article></div>
        <div class="pagination"><button :disabled="searchPage === 1" @click="changePage(-1)">上一页</button><span>第 {{ searchPage }} 页，共 {{ totalPages }} 页</span><button :disabled="searchPage === totalPages" @click="changePage(1)">下一页</button></div>
      </template>

      <template v-else>
        <p class="hint">点击课程卡片即可加入或移出课表</p>
        <div class="group-tools"><select v-model="groupDraft.type"><option v-for="type in groupTypes" :key="type">{{ type }}</option></select><input v-model.number="groupDraft.limit" min="1" placeholder="最多 n" type="number" /><select v-model="groupDraft.unit"><option value="course">门</option><option value="credit">分</option></select><button @click="createGroup">添加组</button><button class="danger" @click="groupDeleteMode = !groupDeleteMode">{{ groupDeleteMode ? '完成' : '删除组' }}</button></div>
        <section v-for="group in groups" :key="group.id" class="group"><header><button v-if="groupDeleteMode" class="danger" @click="deleteGroup(group)">删除</button><button class="fold" @click="group.open = !group.open">{{ group.open ? '收起' : '展开' }}</button><b>{{ group.name }}</b><em :class="{ over: group.limit && groupValue(group) > group.limit }">已选 {{ groupValue(group) }}{{ group.unit === 'course' ? '门' : '分' }} / 应选 {{ group.limit || '不限' }}{{ group.unit === 'course' ? '门' : '分' }}</em></header><div v-show="group.open"><article v-for="course in coursesInGroup(group)" :key="course.key" class="course-row plan-row" :class="{ focused: focusedKey === course.key, selected: activeKeys.includes(course.key) }" @click="toggleSchedule(course)"><div><code>{{ course.id }} · {{ course.credit }} 学分 · {{ course.college || '未填写学院' }}</code><h3>{{ course.name }}</h3><p>{{ course.className }} {{ course.teacher }}</p><small>◷ {{ courseTime(course) }}<br />⌖ {{ course.rooms }}</small></div><button class="danger" @click.stop="removeFromGroup(group, course.key)">移出组</button></article></div></section>
        <div class="course-list plan-list"><article v-for="course in ungroupedPlanCourses" :key="course.key" class="course-row plan-row" :class="{ focused: focusedKey === course.key, selected: activeKeys.includes(course.key) }" @click="toggleSchedule(course)"><div><code>{{ course.id }} · {{ course.credit }} 学分 · {{ course.college || '未填写学院' }}</code><h3>{{ course.name }}</h3><p>{{ course.className }} {{ course.teacher }}</p><small>◷ {{ courseTime(course) }}<br />⌖ {{ course.rooms }}</small></div><div class="row-actions"><button @click.stop="groupPicker = course">加入组</button><button class="danger" @click.stop="removePlan(course.key)">取消</button></div></article></div>
      </template>
    </section>

    <section class="card conflicts"><header><h2>冲突课程</h2><div class="chips"><button v-for="number in conflictWeeks" :key="number" :class="{ active: week === number }" @click="week = number; tab = 'schedule'">{{ number }}</button></div></header><button v-for="item in conflicts" :key="item.key" class="conflict-row" @click="openConflict(item)">{{ days[item.day - 1] }} 第{{ item.period }}节 · {{ item.courses.map(course => course.name).join('、') }} <span>处理 ›</span></button><p v-if="!conflicts.length">当前周次没有课程冲突</p></section>

    <div v-if="groupPicker" class="mask" @click.self="groupPicker = null"><section class="dialog"><button class="close" @click="groupPicker = null">×</button><h2>加入课程组</h2><button v-for="group in groups" :key="group.id" class="choice" @click="addToGroup(group)"><b>{{ group.name }}</b><small>已选 {{ groupValue(group) }}{{ group.unit === 'course' ? '门' : '分' }}</small></button><p v-if="!groups.length">请先创建课程组</p></section></div>
    <div v-if="conflictModal" class="mask" @click.self="conflictModal = null"><section class="dialog"><button class="close" @click="conflictModal = null">×</button><h2>解决课程冲突</h2><p>保留一门课程，其余移出课表。</p><label v-for="course in conflictModal.courses" :key="course.key"><input v-model="keepKey" :value="course.key" type="radio" /> {{ course.name }}（{{ course.className }}）</label><button class="primary" @click="resolveConflict">确认处理</button></section></div>
    <div v-if="notice" class="notice">{{ notice }}</div>
  </main>
</template>

<script>
const COLORS = ['#527dde', '#8b70c9', '#24a37a', '#df9139', '#d9657a', '#3699b5', '#5b9c6b', '#ba6fbe', '#cf7d50', '#4b9a9a', '#7d83d6', '#b39645'];
export default {
  name: 'MobileSchedule',
  data() { return { week: 1, tab: 'schedule', courses: [], planKeys: [], activeKeys: [], groups: [], searchPage: 1, pageSize: 100, filters: { id: '', name: '', className: '', college: '', campus: '', teacher: '', time: '' }, groupDraft: { type: '外语课组', limit: null, unit: 'course' }, groupDeleteMode: false, groupPicker: null, conflictModal: null, keepKey: '', focusedKey: '', notice: '', initial: null, filterFields: [{ key: 'id', label: '课程号' }, { key: 'name', label: '课程名称' }, { key: 'className', label: '班级' }, { key: 'college', label: '学院' }, { key: 'campus', label: '校区' }, { key: 'teacher', label: '教师姓名' }, { key: 'time', label: '上课时间' }], groupTypes: ['外语课组', '公共课组', '专业课组', '选修课组', '必修环节'] }; },
  computed: {
    days() { return ['周一', '周二', '周三', '周四', '周五', '周六', '周日']; },
    filteredCourses() { const f = this.filters; const has = (value, query) => !query || String(value || '').toLowerCase().includes(query.toLowerCase()); return this.courses.filter(course => has(course.id, f.id) && has(course.name, f.name) && has(course.className, f.className) && has(course.college, f.college) && has(course.rooms, f.campus) && has(course.teacher, f.teacher) && has(this.courseTime(course), f.time)); },
    totalPages() { return Math.max(1, Math.ceil(this.filteredCourses.length / this.pageSize)); },
    pagedCourses() { return this.filteredCourses.slice((this.searchPage - 1) * this.pageSize, this.searchPage * this.pageSize); },
    ungroupedPlanCourses() { const grouped = new Set(this.groups.flatMap(group => group.courseKeys)); return this.courses.filter(course => this.planKeys.includes(course.key) && !grouped.has(course.key)); },
    conflicts() { return this.week === 0 ? [] : this.conflictsFor(this.week); },
    conflictWeeks() { return Array.from({ length: 18 }, (_, index) => index + 1).filter(number => this.conflictsFor(number).length); },
  },
  created() { this.loadCourses(); },
  methods: {
    async loadCourses() { try { const response = await fetch(`${process.env.BASE_URL || '/'}lecture_unite.csv`); if (!response.ok) throw new Error(); this.applyRows(this.parseCsv(await response.text())); this.message(`已加载 ${this.courses.length} 条课程`); } catch (error) { this.message('课程数据加载失败，请检查 lecture_unite.csv'); } },
    parseCsv(text) { const rows = []; let row = []; let cell = ''; let quoted = false; const source = text.replace(/^\uFEFF/, ''); for (let index = 0; index < source.length; index += 1) { const char = source[index]; if (char === '"') { if (quoted && source[index + 1] === '"') { cell += '"'; index += 1; } else quoted = !quoted; } else if (char === ',' && !quoted) { row.push(cell.trim()); cell = ''; } else if ((char === '\n' || char === '\r') && !quoted) { if (char === '\r' && source[index + 1] === '\n') index += 1; row.push(cell.trim()); if (row.some(Boolean)) rows.push(row); row = []; cell = ''; } else cell += char; } row.push(cell.trim()); if (row.some(Boolean)) rows.push(row); return rows; },
    applyRows(rows) { const headers = rows[0] || []; const get = (row, field) => String(row[headers.indexOf(field)] || '').trim(); this.courses = rows.slice(1).map(row => { const meetings = []; for (let index = 1; index <= 14; index += 1) { const day = Number(get(row, `星期几${index}`)); const periods = get(row, `节次${index}`); if (day && periods) { const weekText = get(row, `周次${index}`) || '1-18'; meetings.push({ day, periods: this.nums(periods, 11), weeks: this.nums(weekText, 18), weekText, room: get(row, `教室${index}`) || '待定' }); } } const id = get(row, '课程编号'); const className = get(row, '班级') || '未分班'; const teacher = get(row, '主讲教师'); const key = `${id}-${className}-${teacher}`; const hash = [...key].reduce((sum, char) => sum * 31 + char.charCodeAt(0), 0); return { key, id, name: get(row, '课程名称'), className, credit: get(row, '学分') || '—', college: get(row, '学院'), teacher, meetings, rooms: [...new Set(meetings.map(meeting => meeting.room))].join('；'), color: COLORS[Math.abs(hash) % COLORS.length] }; }).filter(course => course.id && course.name); this.initial = this.snapshot(); },
    nums(value, max) { const numbers = []; String(value).match(/\d+(?:\s*[-~至]\s*\d+)?/g)?.forEach(part => { const range = part.match(/\d+/g).map(Number); for (let number = range[0]; number <= (range[1] || range[0]); number += 1) numbers.push(number); }); return numbers.filter(number => number > 0 && number <= max); },
    displayedClasses(day, period) { return this.courses.filter(course => this.activeKeys.includes(course.key)).flatMap(course => course.meetings.filter(meeting => meeting.day === day && meeting.periods.includes(period) && (this.week === 0 || meeting.weeks.includes(this.week))).map((meeting, index) => ({ key: `${course.key}-${index}-${meeting.weekText}`, course, meeting }))); },
    courseTime(course) { return course.meetings.map(meeting => `${meeting.weekText}周，${this.days[meeting.day - 1]} ${meeting.periods.join('-')}节`).join('；'); },
    addToPlan(course) { if (this.planKeys.includes(course.key)) { this.focusPlan(course.key); return; } this.planKeys.push(course.key); this.message('已加入培养方案'); },
    removePlan(key) { this.planKeys = this.planKeys.filter(item => item !== key); this.activeKeys = this.activeKeys.filter(item => item !== key); this.groups.forEach(group => { group.courseKeys = group.courseKeys.filter(item => item !== key); }); },
    toggleSchedule(course) { if (this.activeKeys.includes(course.key)) { this.activeKeys = this.activeKeys.filter(key => key !== course.key); return; } if (!course.meetings.length) { this.message('该课程没有可识别的上课时间'); return; } this.activeKeys.push(course.key); if (this.week === 0 || !course.meetings[0].weeks.includes(this.week)) this.week = course.meetings[0].weeks[0]; },
    focusPlan(key) { this.tab = 'plan'; this.focusedKey = key; this.$nextTick(() => document.querySelector('.focused')?.scrollIntoView({ block: 'center', behavior: 'smooth' })); },
    clearFilters() { Object.keys(this.filters).forEach(key => { this.filters[key] = ''; }); this.searchPage = 1; },
    changePage(step) { this.searchPage = Math.min(this.totalPages, Math.max(1, this.searchPage + step)); },
    createGroup() { const number = this.groups.filter(group => group.type === this.groupDraft.type).length + 1; this.groups.push({ id: Date.now(), type: this.groupDraft.type, name: `${this.groupDraft.type}（${number}）`, limit: this.groupDraft.limit || null, unit: this.groupDraft.unit, courseKeys: [], open: true }); this.groupDraft.limit = null; },
    coursesInGroup(group) { return this.courses.filter(course => group.courseKeys.includes(course.key)); }, groupValue(group) { const courses = this.coursesInGroup(group); return group.unit === 'credit' ? courses.reduce((sum, course) => sum + (Number(course.credit) || 0), 0) : courses.length; },
    addToGroup(group) { if (!group.courseKeys.includes(this.groupPicker.key)) group.courseKeys.push(this.groupPicker.key); this.groupPicker = null; this.message(`已加入 ${group.name}`); }, removeFromGroup(group, key) { group.courseKeys = group.courseKeys.filter(item => item !== key); }, deleteGroup(group) { this.groups = this.groups.filter(item => item.id !== group.id); this.message(`已删除 ${group.name}`); },
    conflictsFor(week) { const cells = {}; this.courses.filter(course => this.activeKeys.includes(course.key)).forEach(course => course.meetings.filter(meeting => meeting.weeks.includes(week)).forEach(meeting => meeting.periods.forEach(period => { const key = `${meeting.day}-${period}`; (cells[key] || (cells[key] = [])).push(course); }))); return Object.entries(cells).filter(([, courses]) => courses.length > 1).map(([key, courses]) => { const [day, period] = key.split('-'); return { key, day: Number(day), period: Number(period), courses }; }); },
    openConflict(item) { this.conflictModal = item; this.keepKey = item.courses[0].key; }, resolveConflict() { const keys = new Set(this.conflictModal.courses.map(course => course.key)); this.activeKeys = this.activeKeys.filter(key => !keys.has(key) || key === this.keepKey); this.conflictModal = null; },
    snapshot() { return JSON.stringify({ planKeys: this.planKeys, activeKeys: this.activeKeys, groups: this.groups }); }, redo() { if (!this.initial) return; const saved = JSON.parse(this.initial); this.planKeys = saved.planKeys; this.activeKeys = saved.activeKeys; this.groups = saved.groups; this.week = 1; this.tab = 'schedule'; this.message('已恢复到打开状态'); }, message(text) { this.notice = text; clearTimeout(this.noticeTimer); this.noticeTimer = setTimeout(() => { this.notice = ''; }, 2200); },
  },
};
</script>

<style scoped>
*{box-sizing:border-box}.mobile-app{min-height:100vh;padding-bottom:16px;background:#f4f7fb;color:#293852;font:13px Arial,"Microsoft YaHei",sans-serif}.mobile-header{height:56px;display:flex;align-items:center;gap:9px;padding:0 14px;background:#fff;border-bottom:1px solid #e2e8f1}.mobile-header b{padding:7px 5px;border-radius:7px;background:#466fd7;color:#fff;font-size:12px}.mobile-header h1{flex:1;margin:0;font-size:17px}.mobile-header button{border:1px solid #cbd8f6;border-radius:5px;padding:6px 9px;background:#f4f7ff;color:#416dd5}.week-control{display:flex;align-items:center;gap:10px;margin:10px;padding:10px 12px;background:#fff;border:1px solid #e2e8f1;border-radius:9px}.week-control strong{min-width:64px}.week-control input{width:100%}.card{margin:10px;overflow:hidden;border:1px solid #e2e8f1;border-radius:10px;background:#fff}.tabs{display:flex;border-bottom:1px solid #e7ecf2}.tabs button{flex:1;border:0;border-bottom:2px solid transparent;padding:13px 3px 11px;background:#fff;color:#65758d;font-size:13px}.tabs .active{border-color:#4773df;color:#4773df;font-weight:bold}.hint{margin:0;padding:9px 12px;color:#8491a4;font-size:12px}.schedule-scroll{overflow-x:auto}.schedule-table{width:100%;min-width:560px;border-collapse:collapse;table-layout:fixed}.schedule-table th,.schedule-table td{border:1px solid #edf0f5}.schedule-table th{height:36px;background:#fbfcfe;color:#65758d;font-weight:normal}.schedule-table th:first-child{width:39px}.schedule-table td{height:70px;padding:2px;vertical-align:top}.schedule-table .split td,.schedule-table .split th{border-top:3px solid #d8dfeb}.class-card{width:100%;min-height:65px;border:0;border-radius:4px;padding:5px;color:#fff;text-align:left;overflow:hidden}.class-card b,.class-card span,.class-card small{display:block;overflow:hidden;text-overflow:ellipsis}.class-card b{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:13px}.class-card span{margin-top:2px;white-space:nowrap;font-size:10px}.class-card small{margin-top:2px;line-height:12px;font-size:9px}.filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;padding:10px}.filters input,.group-tools select,.group-tools input{min-width:0;height:32px;border:1px solid #d8e0eb;border-radius:5px;padding:6px;font-size:12px}.filters button{border:0;border-radius:5px;background:#4773df;color:#fff}.course-list{max-height:480px;overflow:auto;border-top:1px solid #edf0f5}.course-row{display:flex;justify-content:space-between;gap:8px;padding:11px;border-bottom:1px solid #edf0f5}.course-row>div:first-child{min-width:0;flex:1}.course-row code,.course-row small{color:#8491a4;font-size:11px}.course-row h3,.course-row p{margin:3px 0}.course-row h3{font-size:14px}.course-row button,.group-tools button,.pagination button{align-self:center;border:0;border-radius:5px;padding:7px 8px;background:#4773df;color:#fff;font-size:11px;white-space:nowrap}.course-row .outlined{border:1px solid #4773df;background:#fff;color:#4773df}.pagination{display:flex;align-items:center;justify-content:center;gap:10px;padding:10px;color:#718096;font-size:12px}.pagination button:disabled{opacity:.4}.group-tools{display:grid;grid-template-columns:1.3fr .8fr .7fr;gap:6px;padding:9px 10px;background:#f8faff}.group-tools button{padding:7px 4px}.group{margin:8px 10px;overflow:hidden;border:1px solid #e3e8ef;border-radius:7px}.group header{display:flex;align-items:center;gap:6px;padding:7px;background:#fbfcff}.group header b{font-size:13px}.group header em{margin-left:auto;color:#69788d;font-size:10px;font-style:normal;text-align:right}.fold,.danger{border:1px solid #d8e0eb!important;border-radius:5px!important;padding:4px 6px!important;background:#fff!important;color:#6d7d94!important;font-size:10px!important}.danger{border-color:#efcfcc!important;color:#c55d57!important}.over{color:#d6534b!important}.plan-row{padding:9px}.plan-row h3{font-size:15px}.selected{background:#edf4ff}.focused{outline:2px solid #5b85ec;outline-offset:-2px}.row-actions{display:flex;flex-direction:column;justify-content:center;gap:5px}.conflicts header{display:flex;align-items:center;padding:11px;border-bottom:1px solid #edf0f5}.conflicts h2{margin:0;font-size:15px}.chips{margin-left:auto}.chips button{width:24px;height:24px;margin-left:3px;border:0;border-radius:5px;background:#f2f5fa;color:#718096}.chips .active{background:#e85b4d;color:#fff}.conflicts p{padding:2px 12px;color:#8c98aa}.conflict-row{width:100%;border:0;border-bottom:1px solid #edf0f5;padding:11px;background:#fff;color:#53657d;text-align:left}.conflict-row span{float:right;color:#4773df}.mask{position:fixed;z-index:10;inset:0;display:grid;place-items:center;padding:16px;background:#1f2d4277}.dialog{position:relative;width:min(390px,100%);padding:20px;border-radius:10px;background:#fff}.dialog h2{margin-top:0;font-size:17px}.dialog label,.choice{display:block;width:100%;margin:8px 0;border:1px solid #e3e8ef;border-radius:6px;padding:10px;background:#fff;text-align:left}.choice small{display:block;margin-top:3px;color:#8491a4}.close{position:absolute;top:6px;right:10px;border:0;background:transparent;font-size:22px}.primary{width:100%;margin-top:10px;border:0;border-radius:6px;padding:10px;background:#4773df;color:#fff}.notice{position:fixed;z-index:20;bottom:20px;left:50%;transform:translateX(-50%);border-radius:6px;padding:10px 14px;background:#293852;color:#fff;white-space:nowrap}
</style>
